Body:
Very cool plan, but for the time being this handwritten code should do the job:

```js
#!/usr/bin/env node

const fs = require('node:fs')
const os = require('os')

const authFilePath = '~/.local/share/opencode/auth.json'

const getAuthConfigFile = (filePath) => {
	const homeDir = os.homedir()
	return filePath.replace(/^~/, `${homeDir}`)
}

const backup = (filePath, overwrite) => {
	overwrite = Boolean(overwrite)

	const exists = fs.existsSync(`${filePath}.bkp`)

	if(!exists) {
		fs.copyFileSync(filePath, `${filePath}.bkp`)
		console.log(`copied to ${filePath}.bkp`)

		return
	}

	if(overwrite) {
		fs.copyFileSync(filePath, `${filePath}.bkp`)
		console.log(`overwridden to ${filePath}.bkp`)

		return
	}

	console.log('already backed up')
}

const switchConfig = (config, present, neww) => {
	const tmp = {...config[present]}

	config[present] = {...config[neww]}
	config[neww] = tmp

	return config
}

const run = (configPairs) => {
	const resolvedFilePath = getAuthConfigFile(authFilePath)
	const configStr = fs.readFileSync(resolvedFilePath)
	const config = JSON.parse(configStr)

	const newConfig = configPairs.reduce((acc, pair) => {
		return switchConfig(config, pair[0], pair[1])
	}, config)

	console.log("backing up present config")
	backup(resolvedFilePath)

	console.log("switching config")
	fs.writeFileSync(resolvedFilePath, JSON.stringify(newConfig, null, 2))
}

let configPairs = [
	['opencode', 'opencode2'],
	['opencode-go', 'opencode2-go']
]

run(configPairs)
```

Save to `~/.local/bin/switchopencode` given `~/.local/bin` is in `$PATH`

First thing to improve could be to accept the pair as cli args. something like:
```js
const parseArgs = (argv) => {
  const args = argv.slice(2)

  if (args.length === 0) return null

  if (args.length % 2 !== 0) {
    console.error('error: args must be key pairs, blablabla')
    process.exit(1)
  }

  return args.reduce((pairs, arg, i) => {
    if (i % 2 === 0) pairs.push([arg, args[i + 1]])
    return pairs
  }, [])
}

// then in run():
const run = (fallbackPairs) => {
  const configPairs = parseArgs(process.argv) ?? fallbackPairs
  // ... rest unchanged
}
```
I guess what can be done, is if opencode uses some form of `$XDG_SESSION` per session as override for their opencode config, then a command hook can be provided to switch it up.

